cat > src/tmp-check.test.tsx <<'EOF'
import { test, expect } from 'vitest';
import { renderToStaticMarkup } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { DataTable } from './DataTable';
import { App } from './App';
import { generateEmployees } from './data';

const rows = (html: string) => (html.match(/<tr class="g-table__row[^"]*"/g) ?? []);

test('App renders first page sorted by name', () => {
  const html = renderToStaticMarkup(<ThemeProvider theme="light" lang="ru"><App /></ThemeProvider>);
  const r = rows(html);
  console.log('rows', r.length, 'checkboxes', (html.match(/type="checkbox"/g) ?? []).length);
  console.log(html.match(/Всего записей: \d+|1–10 из \d+/g));
  const names = [...html.matchAll(/g-table__cell_primary[^>]*>([^<]+)</g)].map(m => m[1]);
  console.log(names);
  expect(r.length).toBe(10);
  expect([...names].sort(new Intl.Collator('ru').compare)).toEqual(names);
});

test('selection + sort desc salary + page 1 of 20 size', () => {
  const data = generateEmployees(25);
  const html = renderToStaticMarkup(<ThemeProvider theme="light" lang="ru">
    <DataTable data={data} getRowId={(i) => i.id} selectedIds={['1','2']} onSelectionChange={() => {}}
      columns={[{ id: 'name', sortable: true }, { id: 'salary', sortable: true }]}
      defaultSortState={[{ column: 'salary', order: 'desc' }]} pageSizeOptions={[20]} />
  </ThemeProvider>);
  console.log(html.match(/Выбрано: \d+ из \d+|Выбрать все \d+|1–\d+ из \d+/g));
  const salaries = [...html.matchAll(/<td class="g-table__cell">(\d+)<\/td>/g)].map(m => +m[1]);
  console.log(salaries.length, salaries.slice(0, 5));
  expect(salaries).toEqual([...salaries].sort((a, b) => b - a));
  expect(salaries[0]).toBe(Math.max(...data.map(d => d.salary)));
  expect(rows(html).filter(r => r.includes('selected')).length).toBeLessThanOrEqual(2);
});
EOF
